-- Additive recovery/session version and durable notifications. No historical events are fabricated.
ALTER TABLE "User" ADD COLUMN "authVersion" INTEGER NOT NULL DEFAULT 0 CHECK("authVersion">=0);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"tokenHash" TEXT NOT NULL UNIQUE,"authVersion" INTEGER NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
CREATE TABLE "EmailOutbox" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"resetTokenId" TEXT NOT NULL UNIQUE REFERENCES "PasswordResetToken"("id") ON DELETE CASCADE ON UPDATE CASCADE,"recipient" TEXT NOT NULL,"subject" TEXT NOT NULL,"encryptedBody" TEXT NOT NULL,"state" TEXT NOT NULL DEFAULT 'PENDING' CHECK("state" IN ('PENDING','PROCESSING','LOCAL_READY','FAILED')),"attempts" INTEGER NOT NULL DEFAULT 0 CHECK("attempts" BETWEEN 0 AND 5),"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leaseUntil" TIMESTAMP(3),"leaseToken" TEXT,"lastErrorCode" TEXT,"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "EmailOutbox_state_nextAttemptAt_idx" ON "EmailOutbox"("state","nextAttemptAt");
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"orderId" TEXT REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE,"eventKey" TEXT NOT NULL,"kind" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_userId_eventKey_key" UNIQUE("userId","eventKey"));
CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");
